    for(var r=0;r<rows;r++){
      var z=zCache[r][co];
      var px=ox+co*sp, py=oy+r*sp+z;
      r===0?c.moveTo(px,py):c.lineTo(px,py)
    }
    c.stroke()
  }
}
```

