  c._zCache=new Array(1000); // 25*40 = 1000
},
function(c,w,h,t){
  c.fillStyle='rgba(0,0,0,.06)';
  c.fillRect(0,0,w,h);
  var rows=25, cols=40,
      sp=Math.min(w/cols,h/rows),
      ox=(w-cols*sp)/2, oy=(h-rows*sp)/2;
  c.strokeStyle='rgba(100,200,255,.35)';
  c.lineWidth=.8;

  // Fill z-cache once per frame, avoiding per-frame allocation
  var zCache=c._zCache, t2=t*.002, t15=t*.0015, t1=t*.001;
  for(var r=0, idx=0; r<rows; r++){
    for(var co=0; co<cols; co++, idx++){
      zCache[idx]=Math.sin(co*.25+t2)*8+Math.sin(r*.2+t15)*6+Math.sin((co+r)*.15+t1)*4;
    }
  }

  for(var r=0; r<rows; r++){
    c.beginPath();
    var base=r*cols;
    for(var co=0; co<cols; co++){
      var z=zCache[base+co];
      var px=ox+co*sp, py=oy+r*sp+z;
      co===0?c.moveTo(px,py):c.lineTo(px,py)
    }
    c.stroke()
  }
  for(var co=0; co<cols; co++){
    c.beginPath();
    for(var r=0; r<rows; r++){
